<?php

namespace Avunu\WPCloudFiles;

use WP_CLI;
use WP_CLI\Utils;
use WP_Query;

class CLI
{
    /**
     * Delimiter for the `wp search-replace --regex` patterns migrate-urls builds.
     */
    private const REGEX_DELIMITER = '#';

    /**
     * Directories under uploads that are generated by plugins and served
     * publicly, but are not media library attachments.
     */
    private const PUBLIC_GENERATED = [
        'cwicly',
        'fonts',
        'wpcodebox',
        'elementor',
        'generateblocks',
        'oxygen',
        'bb-plugin',
        'et-cache',
        'woo-product-feed-pro',
        'rank-math',
        'nsl_avatars',
    ];

    /**
     * Migrate existing WordPress media library to S3.
     *
     * ## OPTIONS
     *
     * [--limit=<number>]
     * : Maximum number of attachments to process.
     * ---
     * default: 0 (unlimited)
     * ---
     *
     * [--offset=<number>]
     * : Number of attachments to skip.
     * ---
     * default: 0
     * ---
     *
     * [--batch-size=<number>]
     * : Process attachments in batches of this size.
     * ---
     * default: 20
     * ---
     *
     * [--keep-local]
     * : Keep local copy of files after upload.
     *
     * [--force]
     * : Re-upload attachments that may have already been processed.
     *
     * ## EXAMPLES
     *
     *     # Migrate all media files to S3
     *     $ wp wp-cloud-files migrate
     *
     *     # Migrate 50 media files starting from item 100
     *     $ wp wp-cloud-files migrate --limit=50 --offset=100
     *
     *     # Migrate and keep local copies
     *     $ wp wp-cloud-files migrate --keep-local
     *
     *     # Force re-upload all media
     *     $ wp wp-cloud-files migrate --force
     *
     * @param array $args
     * @param array $assoc_args
     */
    public function migrate($args, $assoc_args)
    {
        // Parse arguments
        $limit = (int) ($assoc_args['limit'] ?? 0);
        $offset = (int) ($assoc_args['offset'] ?? 0);
        $batch_size = (int) ($assoc_args['batch-size'] ?? 20);
        $keep_local = isset($assoc_args['keep-local']);
        $force = isset($assoc_args['force']);

        // Validate batch size
        if ($batch_size < 1) {
            $batch_size = 20;
        }

        // Get total count for progress bar
        $total_attachments = $this->get_attachment_count($limit, $offset);
        if ($total_attachments === 0) {
            WP_CLI::warning('No media items found to migrate.');
            return;
        }

        WP_CLI::log(sprintf('Preparing to migrate %d media items to S3...', $total_attachments));

        // Create progress bar
        $progress = Utils\make_progress_bar('Migrating media to S3', $total_attachments);

        // Track statistics
        $stats = [
            'success'  => 0,
            'failed'   => 0,
            'skipped'  => 0,
            'excluded' => 0,
        ];

        // Process in batches
        $processed = 0;
        $mediaHandler = new MediaHandler();
        $s3Client = S3Client::getInstance();

        while ($processed < $total_attachments) {
            $remaining = $limit > 0 ? min($batch_size, $limit - $processed) : $batch_size;
            $attachments = $this->get_attachments($remaining, $offset + $processed);

            if (empty($attachments)) {
                break;
            }

            foreach ($attachments as $attachment) {
                // Get metadata
                $attachment_id = $attachment->ID;
                $metadata = wp_get_attachment_metadata($attachment_id);

                // Check if it's a valid attachment
                if (empty($metadata)) {
                    WP_CLI::debug(sprintf('Skipping attachment #%d - no metadata found.', $attachment_id));
                    $stats['skipped']++;
                    $progress->tick();
                    $processed++;
                    continue;
                }

                // Process the attachment
                $result = $this->process_attachment($attachment_id, $metadata, $mediaHandler, $s3Client, $keep_local, $force);

                // Update stats
                if ($result === true) {
                    $stats['success']++;
                } elseif ($result === null) {
                    $stats['skipped']++;
                } elseif ($result === 'excluded') {
                    $stats['excluded']++;
                } else {
                    $stats['failed']++;
                }

                $progress->tick();
                $processed++;
            }

            // Clear any object cache
            wp_cache_flush();
        }

        $progress->finish();

        // Display results
        WP_CLI::success(sprintf(
            'Migration completed. Successfully migrated: %d, Failed: %d, Skipped: %d, Excluded: %d.',
            $stats['success'],
            $stats['failed'],
            $stats['skipped'],
            $stats['excluded']
        ));
    }

    /**
     * Get the total count of media attachments
     *
     * @param int $limit Maximum number of attachments to count
     * @param int $offset Number of attachments to skip
     * @return int
     */
    private function get_attachment_count(int $limit = 0, int $offset = 0): int
    {
        $args = [
            'post_type'      => 'attachment',
            'post_status'    => 'inherit',
            'fields'         => 'ids',
            'posts_per_page' => 1,
            'offset'         => $offset,
        ];

        $query = new WP_Query($args);
        $count = $query->found_posts - $offset;

        // If limit is set, limit the total count
        if ($limit > 0 && $count > $limit) {
            $count = $limit;
        }

        return max(0, $count);
    }

    /**
     * Get a batch of attachments
     *
     * @param int $limit
     * @param int $offset
     * @return array
     */
    private function get_attachments(int $limit, int $offset = 0): array
    {
        $args = [
            'post_type'      => 'attachment',
            'post_status'    => 'inherit',
            'posts_per_page' => $limit,
            'offset'         => $offset,
            'orderby'        => 'ID',
            'order'          => 'ASC',
        ];

        $query = new WP_Query($args);
        return $query->posts;
    }

    /**
     * Process a single attachment
     *
     * @param int $attachment_id
     * @param array $metadata
     * @param MediaHandler $mediaHandler
     * @param S3Client $s3Client
     * @param bool $keep_local
     * @param bool $force
     * @return bool|string|null True on success, false on failure, null if
     *         skipped, 'excluded' for a private path that stays local.
     */
    private function process_attachment(
        int $attachment_id,
        array $metadata,
        MediaHandler $mediaHandler,
        S3Client $s3Client,
        bool $keep_local,
        bool $force
    ) {
        try {
            $uploads = wp_upload_dir();
            $basedir = trailingslashit($uploads['basedir']);

            // Get the main file path
            $mainFilePath = $mediaHandler->getOriginalFilePath($metadata, $attachment_id);

            if (empty($mainFilePath)) {
                WP_CLI::debug(sprintf('Attachment #%d: Cannot determine file path.', $attachment_id));
                return null;
            }

            $mainLocalPath = $basedir . $mainFilePath;
            $baseDir = dirname($mainFilePath);

            // Private files (S3_EXCLUDE_PREFIXES) are neither uploaded nor
            // deleted, with or without --force.
            if (!Exclusions::shouldOffload($mainFilePath, $attachment_id)) {
                WP_CLI::debug(sprintf('Attachment #%d: Excluded (%s), left local.', $attachment_id, $mainFilePath));
                return 'excluded';
            }

            // Check if main file is already on S3 (unless force option is used)
            if (!$force && $this->isFileOnS3($mainFilePath, $s3Client)) {
                WP_CLI::debug(sprintf('Attachment #%d: Already on S3, skipping.', $attachment_id));
                return null;
            }

            // Check if main file exists locally
            if (!file_exists($mainLocalPath)) {
                WP_CLI::debug(sprintf('Attachment #%d: File not found locally: %s', $attachment_id, $mainLocalPath));
                return false;
            }

            // Upload main file
            if (!$this->uploadFileToS3($mainLocalPath, $mainFilePath, $s3Client, $keep_local, $force)) {
                WP_CLI::debug(sprintf('Attachment #%d: Failed to upload main file.', $attachment_id));
                return false;
            }

            // Process original image if it exists (for scaled images)
            if (!empty($metadata['original_image'])) {
                $originalPath = trailingslashit($baseDir) . $metadata['original_image'];
                $originalLocalPath = $basedir . $originalPath;
                if (file_exists($originalLocalPath)) {
                    $this->uploadFileToS3($originalLocalPath, $originalPath, $s3Client, $keep_local, $force);
                }
            }

            // Process image sizes
            if (!empty($metadata['sizes']) && is_array($metadata['sizes'])) {
                foreach ($metadata['sizes'] as $size) {
                    if (!empty($size['file'])) {
                        $sizePath = trailingslashit($baseDir) . $size['file'];
                        $sizeLocalPath = $basedir . $sizePath;
                        if (file_exists($sizeLocalPath)) {
                            $this->uploadFileToS3($sizeLocalPath, $sizePath, $s3Client, $keep_local, $force);
                        }

                        // Process sources for this size (WebP/AVIF variants)
                        if (!empty($size['sources']) && is_array($size['sources'])) {
                            foreach ($size['sources'] as $source) {
                                if (!empty($source['file'])) {
                                    $sourcePath = trailingslashit($baseDir) . $source['file'];
                                    $sourceLocalPath = $basedir . $sourcePath;
                                    if (file_exists($sourceLocalPath)) {
                                        $this->uploadFileToS3($sourceLocalPath, $sourcePath, $s3Client, $keep_local, $force);
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Process modern format alternatives for main file
            if (!empty($metadata['sources']) && is_array($metadata['sources'])) {
                foreach ($metadata['sources'] as $source) {
                    if (!empty($source['file'])) {
                        $sourcePath = trailingslashit($baseDir) . $source['file'];
                        $sourceLocalPath = $basedir . $sourcePath;
                        if (file_exists($sourceLocalPath)) {
                            $this->uploadFileToS3($sourceLocalPath, $sourcePath, $s3Client, $keep_local, $force);
                        }
                    }
                }
            }

            WP_CLI::debug(sprintf('Attachment #%d: Successfully migrated to S3.', $attachment_id));
            return true;
        } catch (\Exception $e) {
            WP_CLI::debug(sprintf('Attachment #%d: Error: %s', $attachment_id, $e->getMessage()));
            return false;
        }
    }

    /**
     * Check if a file is already on S3
     *
     * @param string $filePath
     * @param S3Client $s3Client
     * @return bool
     */
    private function isFileOnS3(string $filePath, S3Client $s3Client): bool
    {
        try {
            return $s3Client->getFilesystem()->fileExists($filePath);
        } catch (\Exception $e) {
            return false;
        }
    }

    /**
     * Upload a file to S3
     *
     * @param string $localPath
     * @param string $remotePath
     * @param S3Client $s3Client
     * @param bool $keepLocal
     * @param bool $force Overwrite an existing object.
     * @return bool
     */
    private function uploadFileToS3(string $localPath, string $remotePath, S3Client $s3Client, bool $keepLocal, bool $force = false): bool
    {
        if (!file_exists($localPath)) {
            return false;
        }

        // Never replaces an existing object unless --force: the key is left
        // alone and the local file kept, so nothing is lost either way.
        $success = $s3Client->uploadFile($localPath, $remotePath, $force);

        // Delete local file if not keeping local copies
        if ($success && !$keepLocal) {
            @unlink($localPath);
        }

        return $success;
    }


    /**
     * Regenerate thumbnails for document attachments, including those on S3.
     *
     * ## OPTIONS
     *
     * [<attachment-id>]
     * : Process only this specific attachment ID.
     *
     * [--limit=<number>]
     * : Maximum number of attachments to process.
     * ---
     * default: 0 (unlimited)
     * ---
     *
     * [--offset=<number>]
     * : Number of attachments to skip.
     * ---
     * default: 0
     * ---
     *
     * [--force]
     * : Regenerate thumbnails even if they already exist.
     *
     * [--type=<mime-type>]
     * : Only process attachments of this mime type (e.g., application/pdf).
     *   If not specified, all supported document types will be processed.
     *
     * ## EXAMPLES
     *
     *     # Regenerate thumbnails for all supported documents
     *     $ wp wp-cloud-files regenerate-thumbnails
     *
     *     # Regenerate thumbnails for a specific attachment
     *     $ wp wp-cloud-files regenerate-thumbnails 8082
     *
     *     # Regenerate thumbnails only for PDFs
     *     $ wp wp-cloud-files regenerate-thumbnails --type=application/pdf
     *
     *     # Regenerate thumbnails for 50 attachments starting from item 100
     *     $ wp wp-cloud-files regenerate-thumbnails --limit=50 --offset=100
     *
     *     # Force regenerate all thumbnails
     *     $ wp wp-cloud-files regenerate-thumbnails --force
     *
     * @param array $args
     * @param array $assoc_args
     */
    public function regenerate_thumbnails($args, $assoc_args)
    {
        $specific_id = !empty($args[0]) ? (int) $args[0] : null;
        $limit = (int) ($assoc_args['limit'] ?? 0);
        $offset = (int) ($assoc_args['offset'] ?? 0);
        $force = isset($assoc_args['force']);
        $type_filter = $assoc_args['type'] ?? null;

        // Supported document mime types (from DocumentThumbnailer)
        $supported_mime_types = [
            'application/pdf',
            'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'application/msword',
            'application/vnd.oasis.opendocument.text',
            'application/rtf',
            'text/rtf',
            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'application/vnd.ms-excel',
            'application/vnd.oasis.opendocument.spreadsheet',
            'text/csv',
            'application/vnd.openxmlformats-officedocument.presentationml.presentation',
            'application/vnd.ms-powerpoint',
            'application/vnd.oasis.opendocument.presentation',
        ];

        // Handle specific attachment ID
        if ($specific_id) {
            $post = get_post($specific_id);
            if (!$post || $post->post_type !== 'attachment') {
                WP_CLI::error(sprintf('Attachment #%d not found.', $specific_id));
                return;
            }
            $attachments = [$specific_id];
            WP_CLI::log(sprintf('Processing attachment #%d: %s', $specific_id, $post->post_title));
        } else {
            // Filter to specific type if requested
            if ($type_filter) {
                if (!in_array($type_filter, $supported_mime_types, true)) {
                    WP_CLI::error(sprintf('Unsupported mime type: %s', $type_filter));
                    return;
                }
                $mime_types = [$type_filter];
            } else {
                $mime_types = $supported_mime_types;
            }

            $query_args = [
                'post_type'      => 'attachment',
                'post_status'    => 'inherit',
                'post_mime_type' => $mime_types,
                'posts_per_page' => $limit > 0 ? $limit : -1,
                'offset'         => $offset,
                'orderby'        => 'ID',
                'order'          => 'ASC',
                'fields'         => 'ids',
            ];

            $attachments = get_posts($query_args);
        }

        $total = count($attachments);

        if ($total === 0) {
            WP_CLI::warning('No document attachments found.');
            return;
        }

        WP_CLI::log(sprintf('Found %d document attachments to process...', $total));

        $progress = $total > 1 ? Utils\make_progress_bar('Regenerating thumbnails', $total) : null;
        $stats = ['success' => 0, 'failed' => 0, 'skipped' => 0];

        $thumbnailer = new DocumentThumbnailer();
        $s3Client = S3Client::getInstance();
        $uploads = wp_upload_dir();
        $basedir = trailingslashit($uploads['basedir']);

        foreach ($attachments as $attachment_id) {
            $verbose = (bool) $specific_id;
            $metadata = wp_get_attachment_metadata($attachment_id);

            if (!is_array($metadata)) {
                $metadata = [];
            }

            $mime_type = get_post_mime_type($attachment_id);

            if (!$mime_type || !in_array($mime_type, $supported_mime_types, true)) {
                if ($verbose) {
                    WP_CLI::log(sprintf('  Unsupported mime type: %s', $mime_type));
                }
                $stats['skipped']++;
                if ($progress) {
                    $progress->tick();
                }
                continue;
            }

            $attached = (string) get_post_meta($attachment_id, '_wp_attached_file', true);
            if ($attached !== '' && !Exclusions::shouldOffload($attached, $attachment_id)) {
                if ($verbose) {
                    WP_CLI::log('  Excluded by S3_EXCLUDE_PREFIXES, skipping.');
                }
                $stats['skipped']++;
                if ($progress) {
                    $progress->tick();
                }
                continue;
            }

            // Get file info
            $file = get_attached_file($attachment_id);
            $relative_path = str_replace($basedir, '', $file);
            $base_relative_dir = dirname($relative_path);

            // Check if we need to regenerate
            $needs_regen = $force;

            if (!$needs_regen && empty($metadata['sizes'])) {
                $needs_regen = true;
                if ($verbose) {
                    WP_CLI::log('  No sizes in metadata, will generate.');
                }
            }

            // Check if 'full' size exists (needed for media library preview)
            if (!$needs_regen && !isset($metadata['sizes']['full'])) {
                $needs_regen = true;
                if ($verbose) {
                    WP_CLI::log('  Missing "full" size, will generate.');
                }
            }

            // Check if files actually exist on S3
            if (!$needs_regen && !empty($metadata['sizes'])) {
                foreach ($metadata['sizes'] as $size_name => $size_data) {
                    if (!empty($size_data['file'])) {
                        $thumb_path = ltrim("{$base_relative_dir}/{$size_data['file']}", '/');
                        try {
                            if (!$s3Client->getFilesystem()->fileExists($thumb_path)) {
                                $needs_regen = true;
                                if ($verbose) {
                                    WP_CLI::log(sprintf('  Size "%s" missing from S3, will regenerate.', $size_name));
                                }
                                break;
                            }
                        } catch (\Exception $e) {
                            $needs_regen = true;
                            break;
                        }
                    }
                }
            }

            if (!$needs_regen) {
                if ($verbose) {
                    WP_CLI::log('  All thumbnails exist, skipping.');
                }
                $stats['skipped']++;
                if ($progress) {
                    $progress->tick();
                }
                continue;
            }

            // Download from S3 if needed
            $file_dir = dirname($file);
            $cleanup_temp = false;

            if (!file_exists($file)) {
                if ($verbose) {
                    WP_CLI::log('  Downloading from S3...');
                }

                if (!is_dir($file_dir)) {
                    wp_mkdir_p($file_dir);
                }

                $s3_url = wp_get_attachment_url($attachment_id);
                $response = wp_remote_get($s3_url, ['timeout' => 120]);

                if (is_wp_error($response) || wp_remote_retrieve_response_code($response) !== 200) {
                    if ($verbose) {
                        WP_CLI::log('  Failed to download from S3.');
                    }
                    $stats['failed']++;
                    if ($progress) {
                        $progress->tick();
                    }
                    continue;
                }

                file_put_contents($file, wp_remote_retrieve_body($response));
                $cleanup_temp = true;
            }

            // Same set the upload path generates, from one shared definition.
            $sizes = ThumbnailHandler::documentPreviewSizes();

            if (!isset($metadata['sizes'])) {
                $metadata['sizes'] = [];
            }

            $generated = false;
            $original_filename = pathinfo($file, PATHINFO_FILENAME);

            // One render, every size — the document→PDF conversion dominates and
            // does not vary per size.
            $thumbnails = $thumbnailer->generateThumbnails($file, $mime_type, $sizes);

            if ($thumbnails === [] && $verbose) {
                WP_CLI::log('  Failed to generate thumbnails.');
            }

            foreach ($thumbnails as $size_name => $thumbnail_path) {
                if (!file_exists($thumbnail_path)) {
                    continue;
                }

                $thumbnail_filename = "{$original_filename}-{$size_name}.jpg";
                $thumbnail_dest = "{$file_dir}/{$thumbnail_filename}";
                $thumbnail_relative = ltrim("{$base_relative_dir}/{$thumbnail_filename}", '/');

                if (rename($thumbnail_path, $thumbnail_dest)) {
                    $img_dimensions = getimagesize($thumbnail_dest);
                    if ($img_dimensions) {
                        $metadata['sizes'][$size_name] = [
                            'file'      => $thumbnail_filename,
                            'width'     => $img_dimensions[0],
                            'height'    => $img_dimensions[1],
                            'mime-type' => 'image/jpeg',
                        ];

                        if ($size_name === 'full') {
                            $metadata['sizes'][$size_name]['filesize'] = filesize($thumbnail_dest);
                        }

                        if ($s3Client->uploadFile($thumbnail_dest, $thumbnail_relative)) {
                            @unlink($thumbnail_dest);
                            $generated = true;
                            if ($verbose) {
                                WP_CLI::log(sprintf('  Generated and uploaded %s.', $size_name));
                            }
                        }
                    }
                } else {
                    @unlink($thumbnail_path);
                }
            }

            if ($cleanup_temp && file_exists($file)) {
                @unlink($file);
            }

            if ($generated) {
                wp_update_attachment_metadata($attachment_id, $metadata);
                $stats['success']++;
            } else {
                $stats['failed']++;
            }

            if ($progress) {
                $progress->tick();
            }
        }

        if ($progress) {
            $progress->finish();
        }

        WP_CLI::success(sprintf(
            'Thumbnail regeneration completed. Success: %d, Failed: %d, Skipped: %d.',
            $stats['success'],
            $stats['failed'],
            $stats['skipped']
        ));
    }

    /**
     * Rewrite local upload URLs in the database to their S3 public URLs.
     *
     * A convenience wrapper around `wp search-replace` that fills in the local
     * uploads base URL and the configured S3 public URL (including S3_ROOT) for
     * you. Useful after migrating an existing library to S3 so hard-coded upload
     * URLs in post content, meta, and options point at the bucket. The
     * replacement is serialization-safe because it delegates to `wp search-replace`.
     *
     * URLs under S3_EXCLUDE_PREFIXES, and under any --exclude-prefix, are left
     * on the local uploads URL. With any exclusion the replacement runs as a
     * regular expression with a negative lookahead. It runs twice: once for
     * plain URLs and once for the JSON-escaped form (`http:\/\/…`) that block
     * attributes, wp_font_face posts and page builders store.
     *
     * ## OPTIONS
     *
     * [<table>...]
     * : Limit the replacement to specific tables. Defaults to the standard tables.
     *
     * [--exclude-prefix=<prefixes>]
     * : Comma-separated uploads-relative prefixes to leave local as well, such
     * as files that live on a writable volume rather than in the bucket
     * (`cwicly/,fonts/`). Added to S3_EXCLUDE_PREFIXES.
     *
     * [--dry-run]
     * : Show what would be changed without touching the database.
     *
     * [--precise]
     * : Force the use of PHP (instead of SQL) for the replacement.
     *
     * [--all-tables]
     * : Search/replace through all tables registered to $wpdb, not just core tables.
     *
     * [--all-tables-with-prefix]
     * : Search/replace through all tables that share the table prefix.
     *
     * [--network]
     * : Search/replace through all the tables in a multisite network.
     *
     * [--<field>=<value>]
     * : Any other flag is passed straight through to `wp search-replace`.
     *
     * ## EXAMPLES
     *
     *     # Preview the changes first
     *     $ wp wp-cloud-files migrate-urls --dry-run
     *
     *     # Rewrite upload URLs across the database
     *     $ wp wp-cloud-files migrate-urls
     *
     *     # Keep Cwicly CSS and Font Library files on the local uploads URL
     *     $ wp wp-cloud-files migrate-urls --exclude-prefix=cwicly/,fonts/
     *
     *     # Limit to post content and meta
     *     $ wp wp-cloud-files migrate-urls wp_posts wp_postmeta
     *
     * @param array $args
     * @param array $assoc_args
     */
    public function migrate_urls($args, $assoc_args)
    {
        if (!Config::has('S3_PUBLIC_URL')) {
            WP_CLI::error('S3_PUBLIC_URL is not set. Configure the plugin before migrating URLs.');
            return;
        }

        $uploads = wp_upload_dir();
        $from = trailingslashit($uploads['baseurl']);
        $to = S3Client::getInstance()->getPublicUrl('');

        if ($from === $to) {
            WP_CLI::warning('Local uploads URL and S3 public URL are identical; nothing to do.');
            return;
        }

        $prefixes = array_values(array_unique(array_merge(
            Exclusions::prefixes(),
            Exclusions::parse((string) ($assoc_args['exclude-prefix'] ?? ''))
        )));
        unset($assoc_args['exclude-prefix']);

        $isDryRun = isset($assoc_args['dry-run']);

        if (!$isDryRun) {
            WP_CLI::confirm(
                sprintf(
                    'Replace "%s" with "%s" across the database%s?',
                    $from,
                    $to,
                    $prefixes !== [] ? ', except under ' . implode(', ', $prefixes) : ''
                ),
                $assoc_args
            );
        }

        // --yes is consumed by confirm() above; search-replace does not accept it.
        unset($assoc_args['yes']);

        foreach (self::urlReplacements($from, $to, $prefixes) as $replacement) {
            $assoc = $assoc_args;
            if ($replacement['regex']) {
                $assoc['regex'] = true;
                $assoc['regex-delimiter'] = self::REGEX_DELIMITER;
            }

            WP_CLI::log(sprintf('Running: wp search-replace %s %s', $replacement['search'], $replacement['replace']));

            // run_command() takes argv as arrays, so nothing is re-parsed from
            // a string: runcommand('… --flag=\'value\'') kept the quotes.
            WP_CLI::run_command(
                array_merge(['search-replace', $replacement['search'], $replacement['replace']], array_values($args)),
                $assoc
            );
        }
    }

    /**
     * The `wp search-replace` invocations that move $from to $to, leaving
     * every URL under one of $prefixes alone.
     *
     * Two of them: the plain URL, and the JSON-escaped form with "\/" for "/".
     * Without prefixes they are literal strings; with prefixes they are
     * regular expressions (delimiter "#") with a negative lookahead after the
     * base URL, and the replacement is escaped for preg_replace().
     *
     * @param list<string> $prefixes Uploads-relative prefixes to exclude.
     * @return list<array{search: string, replace: string, regex: bool}>
     */
    public static function urlReplacements(string $from, string $to, array $prefixes): array
    {
        $escapeJson = static fn(string $value): string => str_replace('/', '\\/', $value);

        $variants = [
            [$from, $to, $prefixes],
            [$escapeJson($from), $escapeJson($to), array_map($escapeJson, $prefixes)],
        ];

        $replacements = [];

        foreach ($variants as [$search, $replace, $exclude]) {
            if ($exclude === []) {
                $replacements[] = ['search' => $search, 'replace' => $replace, 'regex' => false];
                continue;
            }

            $quoted = array_map(
                static fn(string $prefix): string => preg_quote($prefix, self::REGEX_DELIMITER),
                $exclude
            );

            $replacements[] = [
                'search'  => preg_quote($search, self::REGEX_DELIMITER) . '(?!' . implode('|', $quoted) . ')',
                // preg_replace() treats "\" and "$" in the replacement specially.
                'replace' => str_replace(['\\', '$'], ['\\\\', '\\$'], $replace),
                'regex'   => true,
            ];
        }

        return $replacements;
    }

    /**
     * Show the configuration the plugin is running with.
     *
     * Every setting with its source (constant or environment), the mode the
     * plugin booted in, the exclusion list, and whether the bucket answers.
     * Credentials are never printed.
     *
     * ## OPTIONS
     *
     * [--format=<format>]
     * : Output format.
     * ---
     * default: table
     * options:
     *   - table
     *   - json
     * ---
     *
     * ## EXAMPLES
     *
     *     $ wp wp-cloud-files status
     *     $ wp wp-cloud-files status --format=json
     *
     * @param array $args
     * @param array $assoc_args
     */
    public function status($args, $assoc_args)
    {
        $mode = Plugin::configuredMode();
        $uploads = wp_upload_dir(null, false);

        $settings = [];
        foreach (Config::NAMES as $name) {
            $source = Config::source($name);
            $value = Config::get($name);

            if ($source !== null && in_array($name, Config::SECRETS, true)) {
                $value = '(set)';
            }

            $settings[$name] = ['value' => $value, 'source' => $source];
        }

        $reachable = null;
        if ($mode === Plugin::MODE_FULL) {
            try {
                S3Client::getInstance()->getFilesystem()->fileExists('.wp-cloud-files-status');
                $reachable = true;
            } catch (\Throwable $e) {
                $reachable = false;
            }
        }

        $data = [
            'version'           => self::pluginVersion(),
            'mode'              => $mode ?? 'unconfigured',
            'bucket_reachable'  => $reachable,
            'public_url'        => $mode !== null ? S3Client::getInstance()->getPublicUrl('') : null,
            'uploads_basedir'   => $uploads['basedir'],
            'uploads_baseurl'   => $uploads['baseurl'],
            'exclude_prefixes'  => Exclusions::prefixes(),
            'update_checker'    => isset($GLOBALS['wpcfUpdateChecker']),
            'settings'          => $settings,
        ];

        if (($assoc_args['format'] ?? 'table') === 'json') {
            WP_CLI::line((string) wp_json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
            return;
        }

        $rows = [];
        foreach ($data as $key => $value) {
            if ($key === 'settings') {
                continue;
            }
            $rows[] = ['setting' => $key, 'value' => self::display($value), 'source' => ''];
        }
        foreach ($settings as $name => $setting) {
            $rows[] = [
                'setting' => $name,
                'value'   => self::display($setting['value']),
                'source'  => $setting['source'] ?? 'unset',
            ];
        }

        Utils\format_items('table', $rows, ['setting', 'value', 'source']);
    }

    /**
     * Check that offloaded attachments really are in the bucket.
     *
     * For each attachment, every file its metadata names (original, sizes,
     * modern-format sources) must exist as an object. Attachments under
     * S3_EXCLUDE_PREFIXES are checked the other way round: their main file
     * must NOT be in the bucket. Exits non-zero if anything is missing or
     * leaked.
     *
     * ## OPTIONS
     *
     * [--sample=<number>]
     * : Check this many randomly chosen attachments.
     * ---
     * default: 20
     * ---
     *
     * [--all]
     * : Check every attachment instead of a sample.
     *
     * [--format=<format>]
     * : Output format.
     * ---
     * default: table
     * options:
     *   - table
     *   - json
     * ---
     *
     * ## EXAMPLES
     *
     *     $ wp wp-cloud-files verify
     *     $ wp wp-cloud-files verify --all --format=json
     *
     * @param array $args
     * @param array $assoc_args
     */
    public function verify($args, $assoc_args)
    {
        if (Plugin::configuredMode() === null) {
            WP_CLI::error('The plugin is not configured.');
            return;
        }

        $all = isset($assoc_args['all']);
        $sample = max(1, (int) ($assoc_args['sample'] ?? 20));

        $ids = $all
            ? get_posts([
                'post_type'      => 'attachment',
                'post_status'    => 'inherit',
                'posts_per_page' => -1,
                'orderby'        => 'ID',
                'order'          => 'ASC',
                'fields'         => 'ids',
            ])
            : get_posts([
                'post_type'      => 'attachment',
                'post_status'    => 'inherit',
                'posts_per_page' => $sample,
                'orderby'        => 'rand',
                'fields'         => 'ids',
            ]);

        $s3Client = S3Client::getInstance();
        $mediaHandler = new MediaHandler();

        $report = [
            'attachments' => 0,
            'objects'     => 0,
            'excluded'    => 0,
            'missing'     => [],
            'leaked'      => [],
        ];

        foreach ($ids as $id) {
            $id = (int) $id;
            $metadata = wp_get_attachment_metadata($id);
            $metadata = is_array($metadata) ? $metadata : [];

            $main = $mediaHandler->getOriginalFilePath($metadata, $id);
            if ($main === '') {
                continue;
            }

            $report['attachments']++;

            if (!Exclusions::shouldOffload($main, $id)) {
                $report['excluded']++;
                if ($s3Client->fileExists($main)) {
                    $report['leaked'][] = ['attachment' => $id, 'key' => $main];
                }
                continue;
            }

            foreach (self::attachmentKeys($main, $metadata) as $key) {
                $report['objects']++;
                if (!$s3Client->fileExists($key)) {
                    $report['missing'][] = ['attachment' => $id, 'key' => $key];
                }
            }
        }

        if (($assoc_args['format'] ?? 'table') === 'json') {
            WP_CLI::line((string) wp_json_encode($report, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
        } else {
            $problems = array_merge(
                array_map(static fn(array $row): array => $row + ['problem' => 'missing'], $report['missing']),
                array_map(static fn(array $row): array => $row + ['problem' => 'leaked'], $report['leaked'])
            );
            if ($problems !== []) {
                Utils\format_items('table', $problems, ['attachment', 'key', 'problem']);
            }
        }

        $summary = sprintf(
            'Checked %d attachments (%d objects, %d excluded): %d missing, %d private files in the bucket.',
            $report['attachments'],
            $report['objects'],
            $report['excluded'],
            count($report['missing']),
            count($report['leaked'])
        );

        if ($report['missing'] !== [] || $report['leaked'] !== []) {
            WP_CLI::error($summary);
            return;
        }

        WP_CLI::success($summary);
    }

    /**
     * Every bucket key an attachment's metadata names: the main file, the
     * pre-scaling original, each size and every modern-format source.
     *
     * @param array<string, mixed> $metadata
     * @return list<string>
     */
    public static function attachmentKeys(string $main, array $metadata): array
    {
        $dir = trailingslashit(dirname($main));
        $dir = $dir === './' ? '' : $dir;

        $keys = [$main];

        if (!empty($metadata['original_image'])) {
            $keys[] = $dir . $metadata['original_image'];
        }

        $sources = is_array($metadata['sources'] ?? null) ? $metadata['sources'] : [];

        foreach ((is_array($metadata['sizes'] ?? null) ? $metadata['sizes'] : []) as $size) {
            if (!empty($size['file'])) {
                $keys[] = $dir . $size['file'];
            }
            foreach ((is_array($size['sources'] ?? null) ? $size['sources'] : []) as $source) {
                if (!empty($source['file'])) {
                    $keys[] = $dir . $source['file'];
                }
            }
        }

        foreach ($sources as $source) {
            if (!empty($source['file'])) {
                $keys[] = $dir . $source['file'];
            }
        }

        return array_values(array_unique($keys));
    }

    /**
     * Classify what is in the local uploads directory.
     *
     * Each top-level entry is one of:
     *
     * - attachment: holds media library files (year folders, or a folder
     *   named by an attachment's path);
     * - private: matches S3_EXCLUDE_PREFIXES and must never be public;
     * - public-generated: written by a plugin and served publicly (Cwicly CSS,
     *   the Font Library), but not in the media library;
     * - unknown: anything else, for a human to decide.
     *
     * `non_attachment_prefixes` lists every entry that is not an attachment
     * folder, ready for `migrate-urls --exclude-prefix`.
     *
     * ## OPTIONS
     *
     * [--json]
     * : Print JSON. Same as --format=json.
     *
     * [--format=<format>]
     * : Output format.
     * ---
     * default: table
     * options:
     *   - table
     *   - json
     * ---
     *
     * ## EXAMPLES
     *
     *     $ wp wp-cloud-files inventory
     *     $ wp wp-cloud-files inventory --json > inventory.json
     *
     * @param array $args
     * @param array $assoc_args
     */
    public function inventory($args, $assoc_args)
    {
        $uploads = wp_upload_dir(null, false);
        $basedir = untrailingslashit((string) $uploads['basedir']);

        $data = [
            'basedir'                 => $basedir,
            'baseurl'                 => $uploads['baseurl'],
            'exclude_prefixes'        => Exclusions::prefixes(),
            'entries'                 => self::classifyUploads($basedir, self::attachmentRoots()),
            'non_attachment_prefixes' => [],
        ];

        foreach ($data['entries'] as $entry) {
            if ($entry['class'] !== 'attachment' && $entry['path'] !== '') {
                $data['non_attachment_prefixes'][] = $entry['path'];
            }
        }

        if (isset($assoc_args['json']) || ($assoc_args['format'] ?? 'table') === 'json') {
            WP_CLI::line((string) wp_json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
            return;
        }

        Utils\format_items('table', $data['entries'], ['path', 'class', 'files', 'bytes']);
    }

    /**
     * The first path segment of every attachment's stored path, plus whether
     * any attachment sits directly in the uploads root.
     *
     * @return array{dirs: list<string>, root: bool}
     */
    private static function attachmentRoots(): array
    {
        global $wpdb;

        /** @var list<string> $paths */
        $paths = $wpdb->get_col(
            "SELECT DISTINCT SUBSTRING_INDEX(meta_value, '/', 1) FROM {$wpdb->postmeta}"
            . " WHERE meta_key = '_wp_attached_file' AND meta_value LIKE '%/%'"
        );

        $root = (int) $wpdb->get_var(
            "SELECT COUNT(*) FROM {$wpdb->postmeta} WHERE meta_key = '_wp_attached_file' AND meta_value NOT LIKE '%/%'"
        ) > 0;

        return ['dirs' => array_values(array_map('strval', $paths)), 'root' => $root];
    }

    /**
     * @param array{dirs: list<string>, root: bool} $attachmentRoots
     * @return list<array{path: string, class: string, files: int, bytes: int}>
     */
    public static function classifyUploads(string $basedir, array $attachmentRoots): array
    {
        if (!is_dir($basedir)) {
            return [];
        }

        $entries = [];
        $rootFiles = 0;
        $rootBytes = 0;

        foreach (new \DirectoryIterator($basedir) as $item) {
            if ($item->isDot()) {
                continue;
            }

            if (!$item->isDir()) {
                $rootFiles++;
                $rootBytes += (int) $item->getSize();
                continue;
            }

            $name = $item->getFilename();
            $path = $name . '/';

            if (Exclusions::isExcluded($path)) {
                $class = 'private';
            } elseif (preg_match('/^\d{4}$/', $name) || in_array($name, $attachmentRoots['dirs'], true)) {
                $class = 'attachment';
            } elseif (in_array($name, self::PUBLIC_GENERATED, true)) {
                $class = 'public-generated';
            } else {
                $class = 'unknown';
            }

            [$files, $bytes] = self::measure($item->getPathname());
            $entries[] = ['path' => $path, 'class' => $class, 'files' => $files, 'bytes' => $bytes];
        }

        usort($entries, static fn(array $a, array $b): int => strcmp($a['path'], $b['path']));

        if ($rootFiles > 0) {
            $entries[] = [
                'path'  => '',
                'class' => $attachmentRoots['root'] ? 'attachment' : 'unknown',
                'files' => $rootFiles,
                'bytes' => $rootBytes,
            ];
        }

        return $entries;
    }

    /**
     * @return array{0: int, 1: int} file count and total bytes
     */
    private static function measure(string $dir): array
    {
        $files = 0;
        $bytes = 0;

        $iterator = new \RecursiveIteratorIterator(
            new \RecursiveDirectoryIterator($dir, \FilesystemIterator::SKIP_DOTS)
        );

        foreach ($iterator as $file) {
            if ($file instanceof \SplFileInfo && $file->isFile()) {
                $files++;
                $bytes += (int) $file->getSize();
            }
        }

        return [$files, $bytes];
    }

    private static function pluginVersion(): string
    {
        $data = get_file_data(dirname(__DIR__) . '/index.php', ['Version' => 'Version']);

        return (string) ($data['Version'] ?? '');
    }

    /**
     * @param mixed $value
     */
    private static function display($value): string
    {
        if ($value === null) {
            return '';
        }
        if (is_bool($value)) {
            return $value ? 'true' : 'false';
        }
        if (is_array($value)) {
            return implode(', ', array_map('strval', $value));
        }

        return (string) $value;
    }
}
